#!/usr/bin/env bun
/**
 * JSON Validator - validates JSON input from stdin.
 *
 * Usage:
 *   echo '{"key": "value"}' | bun run src/validate-json.ts
 *   cat file.json | bun run src/validate-json.ts
 *
 * Exit codes:
 *   0 - Valid JSON
 *   1 - Invalid JSON
 */

/**
 * Result of JSON validation.
 */
export interface ValidationResult {
  valid: boolean;
  error?: string;
  position?: number;
}

/**
 * Validate a string as JSON.
 */
export function validateJson(input: string): ValidationResult {
  if (input.trim() === "") {
    return {
      valid: false,
      error: "Empty input",
    };
  }

  try {
    JSON.parse(input);
    return { valid: true };
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Extract position from error message if available
      const posMatch = err.message.match(/position\s+(\d+)/i);
      const position = posMatch ? parseInt(posMatch[1], 10) : undefined;

      return {
        valid: false,
        error: err.message,
        position,
      };
    }
    return {
      valid: false,
      error: String(err),
    };
  }
}

/**
 * Read all input from stdin.
 */
async function readStdin(): Promise<string> {
  const chunks: string[] = [];

  for await (const chunk of Bun.stdin.stream()) {
    chunks.push(new TextDecoder().decode(chunk));
  }

  return chunks.join("");
}

/**
 * Main entry point - run when executed directly.
 */
async function main(): Promise<void> {
  const input = await readStdin();
  const result = validateJson(input);

  if (result.valid) {
    console.log("Valid JSON");
    process.exit(0);
  } else {
    console.error(`Invalid JSON: ${result.error}`);
    if (result.position !== undefined) {
      console.error(`  at position ${result.position}`);
    }
    process.exit(1);
  }
}

// Run main if this file is executed directly
main();

import { describe, expect, test } from "bun:test";
import { validateJson, type ValidationResult } from "./validate-json";

describe("validateJson", () => {
  test("returns valid for a simple object", () => {
    const result = validateJson('{"key": "value"}');
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("returns valid for an array", () => {
    const result = validateJson('[1, 2, 3]');
    expect(result.valid).toBe(true);
  });

  test("returns valid for primitive values", () => {
    expect(validateJson("123").valid).toBe(true);
    expect(validateJson('"hello"').valid).toBe(true);
    expect(validateJson("true").valid).toBe(true);
    expect(validateJson("false").valid).toBe(true);
    expect(validateJson("null").valid).toBe(true);
  });

  test("returns valid for nested structures", () => {
    const json = JSON.stringify({
      users: [
        { name: "Alice", age: 30 },
        { name: "Bob", age: 25 },
      ],
      metadata: { count: 2 },
    });
    expect(validateJson(json).valid).toBe(true);
  });

  test("returns invalid for empty input", () => {
    const result = validateJson("");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });

  test("returns invalid for whitespace-only input", () => {
    const result = validateJson("   \n\t  ");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });

  test("returns invalid for malformed JSON", () => {
    const result = validateJson('{"key": value}');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns invalid for trailing comma", () => {
    const result = validateJson('{"key": "value",}');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns invalid for unquoted keys", () => {
    const result = validateJson("{key: 'value'}");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns invalid for single quotes", () => {
    const result = validateJson("{'key': 'value'}");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });
});

