/** Validation states for the state machine */
const enum State {
  Value,
  String,
  StringEscape,
  StringUnicode,
  Number,
  NumberDecimal,
  NumberExponent,
  NumberExponentSign,
  True1,
  True2,
  True3,
  False1,
  False2,
  False3,
  False4,
  Null1,
  Null2,
  Null3,
