/**
 * Ultra performant JSON validation using a state-machine approach.
 *
 * This validator uses direct character scanning with a minimal state machine
 * to validate JSON syntax without the memory overhead of JSON.parse().
 * It is optimized for validation-only use cases where parsing is not needed.
 *
 * Performance characteristics:
 * - O(n) time complexity where n is input length
 * - O(d) space complexity where d is max nesting depth (typically small)
 * - No intermediate object allocation
 * - Early termination on invalid input
 */

/** Result of JSON validation */
export interface ValidationResult {
  valid: boolean;
  error?: string;
  position?: number;
}

/** Validation states for the state machine */
const enum State {
  Value,
  String,
  StringEscape,
  StringUnicode,
  Number,
  NumberDecimal,
  NumberExponent,
  NumberExponentSign,
  True1,
  True2,
  True3,
  False1,
  False2,
  False3,
  False4,
  Null1,
  Null2,
  Null3,
  AfterValue,
}

/** Container types for nesting tracking */
const enum Container {
  Object,
  Array,
}

/**
 * Validate JSON string with ultra-fast state machine.
 * Returns validation result with error details if invalid.
 */
export function validateJson(input: string): ValidationResult {
  const len = input.length;
  if (len === 0) {
    return { valid: false, error: "Empty input", position: 0 };
  }

  const stack: Container[] = [];
  let state = State.Value;
  let i = 0;
  let unicodeCount = 0;
  let expectingKey = false;
  let expectingColon = false;
  let expectingValue = false;
  let hasValue = false;

  while (i < len) {
    const char = input.charCodeAt(i);

    switch (state) {
      case State.Value: {
        // Skip whitespace
        if (char === 0x20 || char === 0x09 || char === 0x0a || char === 0x0d) {
          i++;
          continue;
        }

        if (char === 0x7b) {
          // {
          stack.push(Container.Object);
          expectingKey = true;
          hasValue = true;
          i++;
          continue;
        }

        if (char === 0x5b) {
          // [
          stack.push(Container.Array);
          hasValue = true;
          i++;
          continue;
        }

        if (char === 0x22) {
          // "
          state = State.String;
          hasValue = true;
          i++;
          continue;
        }

        if (
          char === 0x2d ||
          (char >= 0x30 && char <= 0x39) // - or 0-9
        ) {
          state = State.Number;
          hasValue = true;
          i++;
          continue;
        }

        if (char === 0x74) {
          // t (true)
          state = State.True1;
          hasValue = true;
          i++;
          continue;
        }

        if (char === 0x66) {
          // f (false)
          state = State.False1;
          hasValue = true;
          i++;
          continue;
        }

        if (char === 0x6e) {
          // n (null)
          state = State.Null1;
          hasValue = true;
          i++;
          continue;
        }

        // Handle empty array/object closing
        if (char === 0x5d) {
          // ]
          if (stack.length === 0 || stack[stack.length - 1] !== Container.Array) {
            return { valid: false, error: "Unexpected ]", position: i };
          }
          if (expectingValue) {
            return { valid: false, error: "Expected value before ]", position: i };
          }
          stack.pop();
          state = State.AfterValue;
          i++;
          continue;
        }

        if (char === 0x7d) {
          // }
          if (
            stack.length === 0 ||
            stack[stack.length - 1] !== Container.Object
          ) {
            return { valid: false, error: "Unexpected }", position: i };
          }
          if (expectingValue || expectingColon) {
            return { valid: false, error: "Expected value before }", position: i };
          }
          stack.pop();
          expectingKey = false;
          state = State.AfterValue;
          i++;
          continue;
        }

        return { valid: false, error: `Unexpected character: ${String.fromCharCode(char)}`, position: i };
      }

      case State.String: {
        if (char === 0x22) {
          // "
          state = State.AfterValue;
          i++;
          continue;
        }

        if (char === 0x5c) {
          // \
          state = State.StringEscape;
          i++;
          continue;
        }

        if (char < 0x20) {
          return { valid: false, error: "Invalid control character in string", position: i };
        }

        i++;
        continue;
      }

      case State.StringEscape: {
        if (
          char === 0x22 || // "
          char === 0x5c || // \
          char === 0x2f || // /
          char === 0x62 || // b
          char === 0x66 || // f
          char === 0x6e || // n
          char === 0x72 || // r
          char === 0x74 // t
        ) {
          state = State.String;
          i++;
          continue;
        }

        if (char === 0x75) {
          // u
          state = State.StringUnicode;
          unicodeCount = 0;
          i++;
          continue;
        }

        return { valid: false, error: "Invalid escape sequence", position: i };
      }

      case State.StringUnicode: {
        if (
          (char >= 0x30 && char <= 0x39) || // 0-9
          (char >= 0x41 && char <= 0x46) || // A-F
          (char >= 0x61 && char <= 0x66) // a-f
        ) {
          unicodeCount++;
          if (unicodeCount === 4) {
            state = State.String;
          }
          i++;
          continue;
        }

        return { valid: false, error: "Invalid unicode escape", position: i };
      }

      case State.Number: {
        if (char >= 0x30 && char <= 0x39) {
          // 0-9
          i++;
          continue;
        }

        if (char === 0x2e) {
          // .
          state = State.NumberDecimal;
          i++;
          continue;
        }

        if (char === 0x65 || char === 0x45) {
          // e or E
          state = State.NumberExponent;
          i++;
          continue;
        }

        // End of number
        state = State.AfterValue;
        continue; // Don't increment i, reprocess character
      }

      case State.NumberDecimal: {
        if (char >= 0x30 && char <= 0x39) {
          // 0-9
          i++;
          continue;
        }

        if (char === 0x65 || char === 0x45) {
          // e or E
          state = State.NumberExponent;
          i++;
          continue;
        }

        // End of decimal number
        state = State.AfterValue;
        continue;
      }

      case State.NumberExponent: {
        if (char === 0x2b || char === 0x2d) {
          // + or -
          state = State.NumberExponentSign;
          i++;
          continue;
        }

        if (char >= 0x30 && char <= 0x39) {
          // 0-9
          state = State.NumberExponentSign;
          i++;
          continue;
        }

        return { valid: false, error: "Invalid exponent", position: i };
      }

      case State.NumberExponentSign: {
        if (char >= 0x30 && char <= 0x39) {
          // 0-9
          i++;
          continue;
        }

        // End of number with exponent
        state = State.AfterValue;
        continue;
      }

      case State.True1: {
        if (char === 0x72) {
          // r
          state = State.True2;
          i++;
          continue;
        }
        return { valid: false, error: "Invalid literal, expected 'true'", position: i };
      }

      case State.True2: {
        if (char === 0x75) {
          // u
          state = State.True3;
          i++;
          continue;
        }
        return { valid: false, error: "Invalid literal, expected 'true'", position: i };
      }

      case State.True3: {
        if (char === 0x65) {
          // e
          state = State.AfterValue;
          i++;
          continue;
        }
        return { valid: false, error: "Invalid literal, expected 'true'", position: i };
      }

      case State.False1: {
        if (char === 0x61) {
          // a
          state = State.False2;
          i++;
          continue;
        }
        return { valid: false, error: "Invalid literal, expected 'false'", position: i };
      }

      case State.False2: {
        if (char === 0x6c) {
          // l
          state = State.False3;
          i++;
          continue;
        }
        return { valid: false, error: "Invalid literal, expected 'false'", position: i };
      }

      case State.False3: {
        if (char === 0x73) {
          // s
          state = State.False4;
          i++;
          continue;
        }
        return { valid: false, error: "Invalid literal, expected 'false'", position: i };
      }

      case State.False4: {
        if (char === 0x65) {
          // e
          state = State.AfterValue;
          i++;
          continue;
        }
        return { valid: false, error: "Invalid literal, expected 'false'", position: i };
      }

      case State.Null1: {
        if (char === 0x75) {
          // u
          state = State.Null2;
          i++;
          continue;
        }
        return { valid: false, error: "Invalid literal, expected 'null'", position: i };
      }

      case State.Null2: {
        if (char === 0x6c) {
          // l
          state = State.Null3;
          i++;
          continue;
        }
        return { valid: false, error: "Invalid literal, expected 'null'", position: i };
      }

      case State.Null3: {
        if (char === 0x6c) {
          // l
          state = State.AfterValue;
          i++;
          continue;
        }
        return { valid: false, error: "Invalid literal, expected 'null'", position: i };
      }

      case State.AfterValue: {
        // Skip whitespace
        if (char === 0x20 || char === 0x09 || char === 0x0a || char === 0x0d) {
          i++;
          continue;
        }

        if (stack.length === 0) {
          // No more containers - we should be at end
          return { valid: false, error: "Unexpected content after value", position: i };
        }

        const container = stack[stack.length - 1];

        if (expectingKey) {
          // In object expecting key
          if (char === 0x22) {
            // "
            state = State.String;
            expectingKey = false;
            expectingColon = true;
            i++;
            continue;
          }

          if (char === 0x7d) {
            // }
            stack.pop();
            expectingKey = false;
            i++;
            continue;
          }

          return { valid: false, error: "Expected string key or }", position: i };
        }

        if (expectingColon) {
          if (char === 0x3a) {
            // :
            expectingColon = false;
            expectingValue = true;
            state = State.Value;
            i++;
            continue;
          }

          return { valid: false, error: "Expected ':'", position: i };
        }

        if (char === 0x2c) {
          // ,
          if (container === Container.Object) {
            expectingKey = true;
            expectingValue = false;
          } else {
            state = State.Value;
            expectingValue = true;
          }
          i++;
          continue;
        }

        if (char === 0x5d && container === Container.Array) {
          // ]
          stack.pop();
          expectingValue = false;
          i++;
          continue;
        }

        if (char === 0x7d && container === Container.Object) {
          // }
          stack.pop();
          expectingKey = false;
          expectingValue = false;
          i++;
          continue;
        }

        return { valid: false, error: `Unexpected character: ${String.fromCharCode(char)}`, position: i };
      }
    }
  }

  // End of input
  if (!hasValue) {
    return { valid: false, error: "No value found", position: i };
  }

  if (stack.length > 0) {
    return { valid: false, error: "Unexpected end of input", position: i };
  }

  if (state !== State.AfterValue && state !== State.Number && state !== State.NumberDecimal && state !== State.NumberExponentSign) {
    return { valid: false, error: "Unexpected end of input", position: i };
  }

  return { valid: true };
}

/**
 * Fast check if a string is valid JSON.
 * Returns boolean only - use validateJson for error details.
 */
export function isValidJson(input: string): boolean {
  return validateJson(input).valid;
}

/**
 * Validate JSON from a file path.
 * Reads file and validates content.
 */
export async function validateJsonFile(filePath: string): Promise<ValidationResult> {
  try {
    const file = Bun.file(filePath);
    const content = await file.text();
    return validateJson(content);
  } catch (error) {
    return {
      valid: false,
      error: `Failed to read file: ${error instanceof Error ? error.message : String(error)}`,
    };
  }
}

import { describe, expect, test } from "bun:test";
import { validateJson, isValidJson, validateJsonFile } from "./json-validator";
import { writeFileSync, unlinkSync } from "fs";
import { join } from "path";
import { tmpdir } from "os";

describe("json-validator", () => {
  describe("validateJson", () => {
    describe("valid JSON", () => {
      test("empty object", () => {
        const result = validateJson("{}");
        expect(result.valid).toBe(true);
      });

      test("empty array", () => {
        const result = validateJson("[]");
        expect(result.valid).toBe(true);
      });

      test("simple object with string value", () => {
        const result = validateJson('{"name": "test"}');
        expect(result.valid).toBe(true);
      });

      test("simple object with number value", () => {
        const result = validateJson('{"count": 42}');
        expect(result.valid).toBe(true);
      });

      test("object with multiple fields", () => {
        const result = validateJson('{"a": 1, "b": "two", "c": true}');
        expect(result.valid).toBe(true);
      });

      test("nested objects", () => {
        const result = validateJson('{"outer": {"inner": {"deep": 1}}}');
        expect(result.valid).toBe(true);
      });

      test("array of numbers", () => {
        const result = validateJson("[1, 2, 3, 4, 5]");
        expect(result.valid).toBe(true);
      });

      test("array of strings", () => {
        const result = validateJson('["a", "b", "c"]');
        expect(result.valid).toBe(true);
      });

      test("mixed array", () => {
        const result = validateJson('[1, "two", true, null, {}]');
        expect(result.valid).toBe(true);
      });

      test("nested arrays", () => {
        const result = validateJson("[[1, 2], [3, 4], [[5]]]");
        expect(result.valid).toBe(true);
      });

      test("true literal", () => {
        const result = validateJson("true");
        expect(result.valid).toBe(true);
      });

      test("false literal", () => {
        const result = validateJson("false");
        expect(result.valid).toBe(true);
      });

      test("null literal", () => {
        const result = validateJson("null");
        expect(result.valid).toBe(true);
      });

      test("string literal", () => {
        const result = validateJson('"hello world"');
        expect(result.valid).toBe(true);
      });

      test("integer number", () => {
        const result = validateJson("123");
        expect(result.valid).toBe(true);
      });

      test("negative number", () => {
        const result = validateJson("-456");
        expect(result.valid).toBe(true);
      });

      test("decimal number", () => {
        const result = validateJson("3.14159");
        expect(result.valid).toBe(true);
      });

      test("scientific notation", () => {
        const result = validateJson("1.5e10");
        expect(result.valid).toBe(true);
      });

      test("scientific notation with negative exponent", () => {
        const result = validateJson("1.5e-10");
        expect(result.valid).toBe(true);
      });

      test("scientific notation with uppercase E", () => {
        const result = validateJson("1.5E10");
        expect(result.valid).toBe(true);
      });

      test("scientific notation with positive sign", () => {
        const result = validateJson("1.5e+10");
        expect(result.valid).toBe(true);
      });

      test("string with escape sequences", () => {
        const result = validateJson('"hello\\nworld\\t!"');
        expect(result.valid).toBe(true);
      });

      test("string with unicode escape", () => {
        const result = validateJson('"\\u0041\\u0042"');
        expect(result.valid).toBe(true);
      });

      test("string with escaped quote", () => {
        const result = validateJson('"say \\"hello\\""');
        expect(result.valid).toBe(true);
      });

      test("string with escaped backslash", () => {
        const result = validateJson('"path\\\\to\\\\file"');
        expect(result.valid).toBe(true);
      });

      test("whitespace around values", () => {
        const result = validateJson('  {  "a"  :  1  }  ');
        expect(result.valid).toBe(true);
      });

      test("newlines in JSON", () => {
        const result = validateJson('{\n  "a": 1,\n  "b": 2\n}');
        expect(result.valid).toBe(true);
      });

      test("complex nested structure", () => {
        const json = JSON.stringify({
          users: [
            { id: 1, name: "Alice", active: true },
            { id: 2, name: "Bob", active: false },
          ],
          metadata: {
            total: 2,
            page: 1,
            nested: { deep: { value: null } },
          },
        });
        const result = validateJson(json);
        expect(result.valid).toBe(true);
      });
    });

    describe("invalid JSON", () => {
      test("empty string", () => {
        const result = validateJson("");
        expect(result.valid).toBe(false);
        expect(result.error).toBeDefined();
      });

      test("unclosed object", () => {
        const result = validateJson('{"a": 1');
        expect(result.valid).toBe(false);
        expect(result.error).toContain("end of input");
      });

      test("unclosed array", () => {
        const result = validateJson("[1, 2, 3");
        expect(result.valid).toBe(false);
        expect(result.error).toContain("end of input");
      });

      test("unclosed string", () => {
        const result = validateJson('"hello');
        expect(result.valid).toBe(false);
        expect(result.error).toContain("end of input");
      });

      test("trailing comma in object", () => {
        const result = validateJson('{"a": 1,}');
        expect(result.valid).toBe(false);
      });

      test("trailing comma in array", () => {
        const result = validateJson("[1, 2,]");
        expect(result.valid).toBe(false);
      });

      test("double comma", () => {
        const result = validateJson("[1,, 2]");
        expect(result.valid).toBe(false);
      });

      test("missing colon", () => {
        const result = validateJson('{"a" 1}');
        expect(result.valid).toBe(false);
        expect(result.error).toContain(":");
      });

      test("missing value after colon", () => {
        const result = validateJson('{"a":}');
        expect(result.valid).toBe(false);
      });

      test("unquoted key", () => {
        const result = validateJson("{a: 1}");
        expect(result.valid).toBe(false);
      });

      test("single quotes", () => {
        const result = validateJson("{'a': 1}");
        expect(result.valid).toBe(false);
      });

      test("invalid escape sequence", () => {
        const result = validateJson('"hello\\x"');
        expect(result.valid).toBe(false);
        expect(result.error).toContain("escape");
      });

      test("invalid unicode escape (too short)", () => {
        const result = validateJson('"\\u123"');
        expect(result.valid).toBe(false);
        expect(result.error).toContain("unicode");
      });

      test("invalid unicode escape (invalid hex)", () => {
        const result = validateJson('"\\uGGGG"');
        expect(result.valid).toBe(false);
        expect(result.error).toContain("unicode");
      });

      test("control character in string", () => {
        const result = validateJson('"hello\nworld"');
        expect(result.valid).toBe(false);
        expect(result.error).toContain("control character");
      });

      test("misspelled true", () => {
        const result = validateJson("tru");
        expect(result.valid).toBe(false);
        expect(result.error).toContain("true");
      });

      test("misspelled false", () => {
        const result = validateJson("fals");
        expect(result.valid).toBe(false);
        expect(result.error).toContain("false");
      });

      test("misspelled null", () => {
        const result = validateJson("nul");
        expect(result.valid).toBe(false);
        expect(result.error).toContain("null");
      });

      test("extra content after value", () => {
        const result = validateJson('{"a": 1} extra');
        expect(result.valid).toBe(false);
        expect(result.error).toContain("after value");
      });

      test("multiple values at root", () => {
        const result = validateJson("1 2");
        expect(result.valid).toBe(false);
      });

      test("mismatched brackets", () => {
        const result = validateJson("[1, 2}");
        expect(result.valid).toBe(false);
      });

      test("unexpected closing bracket", () => {
        const result = validateJson("]");
        expect(result.valid).toBe(false);
        expect(result.error).toContain("]");
      });

      test("unexpected closing brace", () => {
        const result = validateJson("}");
        expect(result.valid).toBe(false);
        expect(result.error).toContain("}");
      });
    });

    describe("error position tracking", () => {
      test("reports correct position for error at start", () => {
        const result = validateJson("invalid");
        expect(result.valid).toBe(false);
        expect(result.position).toBe(0);
      });

      test("reports position for error in middle", () => {
        const result = validateJson('{"a": invalid}');
        expect(result.valid).toBe(false);
        expect(result.position).toBeGreaterThan(5);
      });
    });
  });

  describe("isValidJson", () => {
    test("returns true for valid JSON", () => {
      expect(isValidJson('{"valid": true}')).toBe(true);
    });

    test("returns false for invalid JSON", () => {
      expect(isValidJson("not json")).toBe(false);
    });
  });

  describe("validateJsonFile", () => {
    const tempDir = tmpdir();

    test("validates valid JSON file", async () => {
      const filePath = join(tempDir, "test-valid.json");
      writeFileSync(filePath, '{"test": true}');

      try {
        const result = await validateJsonFile(filePath);
        expect(result.valid).toBe(true);
      } finally {
        unlinkSync(filePath);
      }
    });

    test("validates invalid JSON file", async () => {
      const filePath = join(tempDir, "test-invalid.json");
      writeFileSync(filePath, "not valid json");

      try {
        const result = await validateJsonFile(filePath);
        expect(result.valid).toBe(false);
        expect(result.error).toBeDefined();
      } finally {
        unlinkSync(filePath);
      }
    });

    test("handles non-existent file", async () => {
      const result = await validateJsonFile("/nonexistent/path/to/file.json");
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Failed to read file");
    });
  });
});

