/**
 * Ultra performant JSON validation using a state-machine approach.
 *
 * This validator uses direct character scanning with a minimal state machine
 * to validate JSON syntax without the memory overhead of JSON.parse().
 * It is optimized for validation-only use cases where parsing is not needed.
 *
 * Performance characteristics:
 * - O(n) time complexity where n is input length
 * - O(d) space complexity where d is max nesting depth (typically small)
 * - No intermediate object allocation
 * - Early termination on invalid input
 */

/** Result of JSON validation */
export interface ValidationResult {
  valid: boolean;
  error?: string;
  position?: number;
}

/** Context states for tracking where we are in the JSON structure */
const enum Context {
  None,
  Object,
  Array,
}

/** What we expect next within a container */
const enum Expect {
  Value,
  Key,
  Colon,
  CommaOrEnd,
}

/**
 * Validate JSON string with ultra-fast state machine.
 * Returns validation result with error details if invalid.
 */
export function validateJson(input: string): ValidationResult {
  const len = input.length;
  if (len === 0) {
    return { valid: false, error: "Empty input", position: 0 };
  }

  // Stack to track nested containers and their expectations
  const contextStack: Context[] = [];
  const expectStack: Expect[] = [];
  let i = 0;

  // Skip leading whitespace
  while (i < len && isWhitespace(input.charCodeAt(i))) {
    i++;
  }

  if (i >= len) {
    return { valid: false, error: "Empty input", position: 0 };
  }

  // Parse the root value
  const result = parseValue(input, i, len, contextStack, expectStack);
  if (!result.valid) {
    return result;
  }

  i = result.position!;

  // Skip trailing whitespace
  while (i < len && isWhitespace(input.charCodeAt(i))) {
    i++;
  }

  // Should be at end
  if (i < len) {
    return { valid: false, error: "Unexpected content after value", position: i };
  }

  return { valid: true };
}

function isWhitespace(char: number): boolean {
  return char === 0x20 || char === 0x09 || char === 0x0a || char === 0x0d;
}

function parseValue(
  input: string,
  i: number,
  len: number,
  contextStack: Context[],
  expectStack: Expect[]
): ValidationResult & { position?: number } {
  // Skip whitespace
  while (i < len && isWhitespace(input.charCodeAt(i))) {
    i++;
  }

  if (i >= len) {
    return { valid: false, error: "Unexpected end of input", position: i };
  }

  const char = input.charCodeAt(i);

  // Object
  if (char === 0x7b) {
    return parseObject(input, i, len, contextStack, expectStack);
  }

  // Array
  if (char === 0x5b) {
    return parseArray(input, i, len, contextStack, expectStack);
  }

  // String
  if (char === 0x22) {
    return parseString(input, i, len);
  }

  // Number
  if (char === 0x2d || (char >= 0x30 && char <= 0x39)) {
    return parseNumber(input, i, len);
  }

  // true
  if (char === 0x74) {
    return parseLiteral(input, i, len, "true");
  }

  // false
  if (char === 0x66) {
    return parseLiteral(input, i, len, "false");
  }

  // null
  if (char === 0x6e) {
    return parseLiteral(input, i, len, "null");
  }

  return {
    valid: false,
    error: `Unexpected character: ${String.fromCharCode(char)}`,
    position: i,
  };
}

function parseObject(
  input: string,
  i: number,
  len: number,
  contextStack: Context[],
  expectStack: Expect[]
): ValidationResult & { position?: number } {
  i++; // Skip {

  // Skip whitespace
  while (i < len && isWhitespace(input.charCodeAt(i))) {
    i++;
  }

  if (i >= len) {
    return { valid: false, error: "Unexpected end of input in object", position: i };
  }

  // Empty object
  if (input.charCodeAt(i) === 0x7d) {
    return { valid: true, position: i + 1 };
  }

  // Parse key-value pairs
  while (true) {
    // Skip whitespace
    while (i < len && isWhitespace(input.charCodeAt(i))) {
      i++;
    }

    if (i >= len) {
      return { valid: false, error: "Unexpected end of input in object", position: i };
    }

    // Expect string key
    if (input.charCodeAt(i) !== 0x22) {
      return { valid: false, error: "Expected string key", position: i };
    }

    const keyResult = parseString(input, i, len);
    if (!keyResult.valid) {
      return keyResult;
    }
    i = keyResult.position!;

    // Skip whitespace
    while (i < len && isWhitespace(input.charCodeAt(i))) {
      i++;
    }

    if (i >= len) {
      return { valid: false, error: "Unexpected end of input, expected ':'", position: i };
    }

    // Expect colon
    if (input.charCodeAt(i) !== 0x3a) {
      return { valid: false, error: "Expected ':'", position: i };
    }
    i++;

    // Parse value
    const valueResult = parseValue(input, i, len, contextStack, expectStack);
    if (!valueResult.valid) {
      return valueResult;
    }
    i = valueResult.position!;

    // Skip whitespace
    while (i < len && isWhitespace(input.charCodeAt(i))) {
      i++;
    }

    if (i >= len) {
      return { valid: false, error: "Unexpected end of input in object", position: i };
    }

    const nextChar = input.charCodeAt(i);

    // End of object
    if (nextChar === 0x7d) {
      return { valid: true, position: i + 1 };
    }

    // Comma for next pair
    if (nextChar === 0x2c) {
      i++;
      continue;
    }

    return { valid: false, error: "Expected ',' or '}'", position: i };
  }
}

function parseArray(
  input: string,
  i: number,
  len: number,
  contextStack: Context[],
  expectStack: Expect[]
): ValidationResult & { position?: number } {
  i++; // Skip [

  // Skip whitespace
  while (i < len && isWhitespace(input.charCodeAt(i))) {
    i++;
  }

  if (i >= len) {
    return { valid: false, error: "Unexpected end of input in array", position: i };
  }

  // Empty array
  if (input.charCodeAt(i) === 0x5d) {
    return { valid: true, position: i + 1 };
  }

  // Parse values
  while (true) {
    const valueResult = parseValue(input, i, len, contextStack, expectStack);
    if (!valueResult.valid) {
      return valueResult;
    }
    i = valueResult.position!;

    // Skip whitespace
    while (i < len && isWhitespace(input.charCodeAt(i))) {
      i++;
    }

    if (i >= len) {
      return { valid: false, error: "Unexpected end of input in array", position: i };
    }

    const nextChar = input.charCodeAt(i);

    // End of array
    if (nextChar === 0x5d) {
      return { valid: true, position: i + 1 };
    }

    // Comma for next value
    if (nextChar === 0x2c) {
      i++;
      continue;
    }

    return { valid: false, error: "Expected ',' or ']'", position: i };
  }
}

function parseString(
  input: string,
  i: number,
  len: number
): ValidationResult & { position?: number } {
  i++; // Skip opening "

  while (i < len) {
    const char = input.charCodeAt(i);

    // End of string
    if (char === 0x22) {
      return { valid: true, position: i + 1 };
    }

    // Escape sequence
    if (char === 0x5c) {
      i++;
      if (i >= len) {
        return { valid: false, error: "Unexpected end of input in string escape", position: i };
      }

      const escapeChar = input.charCodeAt(i);

      // Simple escapes
      if (
        escapeChar === 0x22 || // "
        escapeChar === 0x5c || // \
        escapeChar === 0x2f || // /
        escapeChar === 0x62 || // b
        escapeChar === 0x66 || // f
        escapeChar === 0x6e || // n
        escapeChar === 0x72 || // r
        escapeChar === 0x74    // t
      ) {
        i++;
        continue;
      }

      // Unicode escape
      if (escapeChar === 0x75) {
        i++;
        // Need 4 hex digits
        for (let j = 0; j < 4; j++) {
          if (i >= len) {
            return { valid: false, error: "Unexpected end of input in unicode escape", position: i };
          }
          const hexChar = input.charCodeAt(i);
          if (
            !((hexChar >= 0x30 && hexChar <= 0x39) || // 0-9
              (hexChar >= 0x41 && hexChar <= 0x46) || // A-F
              (hexChar >= 0x61 && hexChar <= 0x66))   // a-f
          ) {
            return { valid: false, error: "Invalid unicode escape", position: i };
          }
          i++;
        }
        continue;
      }

      return { valid: false, error: "Invalid escape sequence", position: i };
    }

    // Control characters not allowed
    if (char < 0x20) {
      return { valid: false, error: "Invalid control character in string", position: i };
    }

    i++;
  }

  return { valid: false, error: "Unexpected end of input in string", position: i };
}

function parseNumber(
  input: string,
  i: number,
  len: number
): ValidationResult & { position?: number } {
  const start = i;

  // Optional minus
  if (i < len && input.charCodeAt(i) === 0x2d) {
    i++;
  }

  if (i >= len) {
    return { valid: false, error: "Unexpected end of input in number", position: i };
  }

  // Integer part
  const firstDigit = input.charCodeAt(i);
  if (firstDigit === 0x30) {
    // Leading zero - must be just 0
    i++;
  } else if (firstDigit >= 0x31 && firstDigit <= 0x39) {
    // 1-9 followed by any digits
    i++;
    while (i < len && input.charCodeAt(i) >= 0x30 && input.charCodeAt(i) <= 0x39) {
      i++;
    }
  } else {
    return { valid: false, error: "Invalid number", position: i };
  }

  // Fraction part
  if (i < len && input.charCodeAt(i) === 0x2e) {
    i++;
    if (i >= len || input.charCodeAt(i) < 0x30 || input.charCodeAt(i) > 0x39) {
      return { valid: false, error: "Invalid number: expected digit after decimal point", position: i };
    }
    while (i < len && input.charCodeAt(i) >= 0x30 && input.charCodeAt(i) <= 0x39) {
      i++;
    }
  }

  // Exponent part
  if (i < len && (input.charCodeAt(i) === 0x65 || input.charCodeAt(i) === 0x45)) {
    i++;
    // Optional sign
    if (i < len && (input.charCodeAt(i) === 0x2b || input.charCodeAt(i) === 0x2d)) {
      i++;
    }
    if (i >= len || input.charCodeAt(i) < 0x30 || input.charCodeAt(i) > 0x39) {
      return { valid: false, error: "Invalid number: expected digit in exponent", position: i };
    }
    while (i < len && input.charCodeAt(i) >= 0x30 && input.charCodeAt(i) <= 0x39) {
      i++;
    }
  }

  return { valid: true, position: i };
}

function parseLiteral(
  input: string,
  i: number,
  len: number,
  expected: string
): ValidationResult & { position?: number } {
  for (let j = 0; j < expected.length; j++) {
    if (i + j >= len) {
      return { valid: false, error: `Unexpected end of input, expected '${expected}'`, position: i + j };
    }
    if (input.charCodeAt(i + j) !== expected.charCodeAt(j)) {
      return { valid: false, error: `Invalid literal, expected '${expected}'`, position: i + j };
    }
  }
  return { valid: true, position: i + expected.length };
}

/**
 * Fast check if a string is valid JSON.
 * Returns boolean only - use validateJson for error details.
 */
export function isValidJson(input: string): boolean {
  return validateJson(input).valid;
}

/**
 * Validate JSON from a file path.
 * Reads file and validates content.
 */
export async function validateJsonFile(filePath: string): Promise<ValidationResult> {
  try {
    const file = Bun.file(filePath);
    const content = await file.text();
    return validateJson(content);
  } catch (error) {
    return {
      valid: false,
      error: `Failed to read file: ${error instanceof Error ? error.message : String(error)}`,
    };
  }
}

